insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-black-holes-trivia',
  'Black Holes Trivia: Event Horizons and Cosmic Giants',
  'Eight questions on event horizons, Hawking radiation and the black holes at the heart of galaxies, from theory to the first image.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"What is the boundary around a black hole beyond which nothing, not even light, can escape?","options":[{"id":"a","text":"The photosphere","is_correct":false},{"id":"b","text":"The event horizon","is_correct":true},{"id":"c","text":"The corona","is_correct":false},{"id":"d","text":"The magnetosphere","is_correct":false}],"explanation":"The event horizon marks the point of no return, where escape velocity exceeds the speed of light."},{"id":"q2","question":"Which theory, published by Albert Einstein in 1915, predicts the existence of black holes?","options":[{"id":"a","text":"Special relativity","is_correct":false},{"id":"b","text":"Quantum electrodynamics","is_correct":false},{"id":"c","text":"General relativity","is_correct":true},{"id":"d","text":"String theory","is_correct":false}],"explanation":"General relativity describes gravity as the curvature of spacetime, which allows black holes to form."},{"id":"q3","question":"Which physicist popularized the term ''black hole'' in 1967?","options":[{"id":"a","text":"Stephen Hawking","is_correct":false},{"id":"b","text":"Karl Schwarzschild","is_correct":false},{"id":"c","text":"Roger Penrose","is_correct":false},{"id":"d","text":"John Archibald Wheeler","is_correct":true}],"explanation":"Wheeler popularized the name ''black hole'' at a 1967 conference, replacing ''gravitationally collapsed star''."},{"id":"q4","question":"What type of black hole sits at the center of most large galaxies, including the Milky Way?","options":[{"id":"a","text":"Supermassive","is_correct":true},{"id":"b","text":"Stellar-mass","is_correct":false},{"id":"c","text":"Primordial","is_correct":false},{"id":"d","text":"Intermediate-mass","is_correct":false}],"explanation":"Supermassive black holes hold millions to billions of times the mass of the Sun."},{"id":"q5","question":"What is the name of the supermassive black hole at the center of the Milky Way?","options":[{"id":"a","text":"Cygnus X-1","is_correct":false},{"id":"b","text":"M87*","is_correct":false},{"id":"c","text":"Centaurus A","is_correct":false},{"id":"d","text":"Sagittarius A*","is_correct":true}],"explanation":"Sagittarius A* lies about 26,000 light-years away and has about 4 million solar masses."},{"id":"q6","question":"What theoretical radiation, predicted by Stephen Hawking in 1974, lets black holes slowly lose mass?","options":[{"id":"a","text":"Cherenkov radiation","is_correct":false},{"id":"b","text":"Synchrotron radiation","is_correct":false},{"id":"c","text":"Hawking radiation","is_correct":true},{"id":"d","text":"Bremsstrahlung radiation","is_correct":false}],"explanation":"Hawking showed that quantum effects near the event horizon make black holes emit faint radiation."},{"id":"q7","question":"Who found the first exact black hole solution to Einstein''s field equations, in 1916?","options":[{"id":"a","text":"Karl Schwarzschild","is_correct":true},{"id":"b","text":"Arthur Eddington","is_correct":false},{"id":"c","text":"Subrahmanyan Chandrasekhar","is_correct":false},{"id":"d","text":"J. Robert Oppenheimer","is_correct":false}],"explanation":"Schwarzschild solved the equations for a spherical, non-rotating mass while serving in World War I."},{"id":"q8","question":"Which black hole''s shadow was captured in the first direct image, released by the Event Horizon Telescope in 2019?","options":[{"id":"a","text":"Sagittarius A*","is_correct":false},{"id":"b","text":"Cygnus X-1","is_correct":false},{"id":"c","text":"Ton 618","is_correct":false},{"id":"d","text":"M87*","is_correct":true}],"explanation":"The EHT imaged the glowing gas ring around M87*, the black hole at the center of galaxy Messier 87."}]'::jsonb,
  null,
  array['science', 'trivia', 'black holes', 'space', 'astronomy']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-agujeros-negros',
  'Trivia de agujeros negros: horizontes de sucesos y gigantes',
  'Ocho preguntas sobre horizontes de sucesos, radiación de Hawking y los agujeros negros del centro de las galaxias.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"¿Cómo se llama el límite de un agujero negro a partir del cual nada, ni siquiera la luz, puede escapar?","options":[{"id":"a","text":"La fotosfera","is_correct":false},{"id":"b","text":"El horizonte de sucesos","is_correct":true},{"id":"c","text":"La corona","is_correct":false},{"id":"d","text":"La magnetosfera","is_correct":false}],"explanation":"El horizonte de sucesos marca el punto de no retorno, donde la velocidad de escape supera la de la luz."},{"id":"q2","question":"¿Qué teoría, publicada por Albert Einstein en 1915, predice la existencia de los agujeros negros?","options":[{"id":"a","text":"La relatividad especial","is_correct":false},{"id":"b","text":"La electrodinámica cuántica","is_correct":false},{"id":"c","text":"La relatividad general","is_correct":true},{"id":"d","text":"La teoría de cuerdas","is_correct":false}],"explanation":"La relatividad general describe la gravedad como la curvatura del espacio-tiempo, lo que permite los agujeros negros."},{"id":"q3","question":"¿Qué físico popularizó el término «agujero negro» en 1967?","options":[{"id":"a","text":"Stephen Hawking","is_correct":false},{"id":"b","text":"Karl Schwarzschild","is_correct":false},{"id":"c","text":"Roger Penrose","is_correct":false},{"id":"d","text":"John Archibald Wheeler","is_correct":true}],"explanation":"Wheeler popularizó el nombre «agujero negro» en una conferencia de 1967, en lugar de «estrella colapsada gravitacionalmente»."},{"id":"q4","question":"¿Qué tipo de agujero negro se encuentra en el centro de la mayoría de las galaxias grandes, incluida la Vía Láctea?","options":[{"id":"a","text":"Supermasivo","is_correct":true},{"id":"b","text":"De masa estelar","is_correct":false},{"id":"c","text":"Primordial","is_correct":false},{"id":"d","text":"De masa intermedia","is_correct":false}],"explanation":"Los agujeros negros supermasivos contienen de millones a miles de millones de masas solares."},{"id":"q5","question":"¿Cómo se llama el agujero negro supermasivo del centro de la Vía Láctea?","options":[{"id":"a","text":"Cygnus X-1","is_correct":false},{"id":"b","text":"M87*","is_correct":false},{"id":"c","text":"Centauro A","is_correct":false},{"id":"d","text":"Sagitario A*","is_correct":true}],"explanation":"Sagitario A* está a unos 26.000 años luz y tiene alrededor de 4 millones de masas solares."},{"id":"q6","question":"¿Qué radiación teórica, predicha por Stephen Hawking en 1974, permite que los agujeros negros pierdan masa?","options":[{"id":"a","text":"La radiación Cherenkov","is_correct":false},{"id":"b","text":"La radiación de sincrotrón","is_correct":false},{"id":"c","text":"La radiación de Hawking","is_correct":true},{"id":"d","text":"La radiación de frenado","is_correct":false}],"explanation":"Hawking demostró que los efectos cuánticos cerca del horizonte de sucesos hacen que los agujeros negros emitan radiación."},{"id":"q7","question":"¿Quién encontró la primera solución exacta de agujero negro de las ecuaciones de Einstein, en 1916?","options":[{"id":"a","text":"Karl Schwarzschild","is_correct":true},{"id":"b","text":"Arthur Eddington","is_correct":false},{"id":"c","text":"Subrahmanyan Chandrasekhar","is_correct":false},{"id":"d","text":"J. Robert Oppenheimer","is_correct":false}],"explanation":"Schwarzschild resolvió las ecuaciones para una masa esférica sin rotación mientras servía en la Primera Guerra Mundial."},{"id":"q8","question":"¿De qué agujero negro obtuvo el telescopio Event Horizon la primera imagen directa de su sombra, publicada en 2019?","options":[{"id":"a","text":"Sagitario A*","is_correct":false},{"id":"b","text":"Cygnus X-1","is_correct":false},{"id":"c","text":"Ton 618","is_correct":false},{"id":"d","text":"M87*","is_correct":true}],"explanation":"El EHT fotografió el anillo de gas brillante alrededor de M87*, el agujero negro del centro de la galaxia Messier 87."}]'::jsonb,
  null,
  array['ciencia', 'trivia', 'agujeros negros', 'espacio', 'astronomía']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-dna-and-genetics-trivia',
  'DNA and Genetics Trivia: The Code of Life',
  'Eight questions on the double helix, base pairs, Mendel''s peas and the scientists who revealed how inheritance works.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"What is the shape of the DNA molecule described by Watson and Crick in 1953?","options":[{"id":"a","text":"A triple strand","is_correct":false},{"id":"b","text":"A flat folded sheet","is_correct":false},{"id":"c","text":"A double helix","is_correct":true},{"id":"d","text":"A single coiled loop","is_correct":false}],"explanation":"DNA is two strands twisted into a double helix, with base pairs forming its rungs."},{"id":"q2","question":"Which pair of scientists published the double-helix model of DNA in 1953?","options":[{"id":"a","text":"James Watson and Francis Crick","is_correct":true},{"id":"b","text":"Charles Darwin and Alfred Russel Wallace","is_correct":false},{"id":"c","text":"Gregor Mendel and Thomas Hunt Morgan","is_correct":false},{"id":"d","text":"Rosalind Franklin and Maurice Wilkins","is_correct":false}],"explanation":"Watson and Crick built the model in Cambridge, relying on X-ray data produced by Rosalind Franklin."},{"id":"q3","question":"Whose X-ray diffraction image known as Photo 51 was key to revealing DNA''s structure?","options":[{"id":"a","text":"Marie Curie","is_correct":false},{"id":"b","text":"Barbara McClintock","is_correct":false},{"id":"c","text":"Lise Meitner","is_correct":false},{"id":"d","text":"Rosalind Franklin","is_correct":true}],"explanation":"Franklin''s Photo 51 showed the X pattern that revealed DNA is a helix."},{"id":"q4","question":"Which are the four nitrogenous bases found in DNA?","options":[{"id":"a","text":"Adenine, guanine, cytosine and uracil","is_correct":false},{"id":"b","text":"Adenine, guanine, cytosine and thymine","is_correct":true},{"id":"c","text":"Adenine, guanine, phosphate and thymine","is_correct":false},{"id":"d","text":"Adenine, glucose, cytosine and thymine","is_correct":false}],"explanation":"DNA uses adenine, guanine, cytosine and thymine; uracil replaces thymine in RNA."},{"id":"q5","question":"In DNA, which base always pairs with adenine?","options":[{"id":"a","text":"Guanine","is_correct":false},{"id":"b","text":"Cytosine","is_correct":false},{"id":"c","text":"Uracil","is_correct":false},{"id":"d","text":"Thymine","is_correct":true}],"explanation":"Adenine pairs with thymine (A–T) and guanine pairs with cytosine (G–C)."},{"id":"q6","question":"Which monk discovered the basic laws of inheritance in the 1860s by experimenting with pea plants?","options":[{"id":"a","text":"Gregor Mendel","is_correct":true},{"id":"b","text":"Charles Darwin","is_correct":false},{"id":"c","text":"Thomas Hunt Morgan","is_correct":false},{"id":"d","text":"Hugo de Vries","is_correct":false}],"explanation":"Mendel''s pea experiments in his monastery garden laid the foundation of genetics."},{"id":"q7","question":"In which structure inside a eukaryotic cell is most of its DNA located?","options":[{"id":"a","text":"The ribosome","is_correct":false},{"id":"b","text":"The nucleus","is_correct":true},{"id":"c","text":"The Golgi apparatus","is_correct":false},{"id":"d","text":"The lysosome","is_correct":false}],"explanation":"Most DNA sits in the nucleus; mitochondria also carry a small genome of their own."},{"id":"q8","question":"How many chromosomes does a typical human cell contain?","options":[{"id":"a","text":"23","is_correct":false},{"id":"b","text":"44","is_correct":false},{"id":"c","text":"46","is_correct":true},{"id":"d","text":"48","is_correct":false}],"explanation":"Human cells carry 46 chromosomes in 23 pairs, one set from each parent."}]'::jsonb,
  null,
  array['science', 'trivia', 'dna', 'genetics', 'biology']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
