values (
  'es-trivia-adn-y-genetica',
  'Trivia de ADN y genética: el código de la vida',
  'Ocho preguntas sobre la doble hélice, los pares de bases, los guisantes de Mendel y quienes revelaron cómo funciona la herencia.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"¿Qué forma tiene la molécula de ADN descrita por Watson y Crick en 1953?","options":[{"id":"a","text":"Una triple hebra","is_correct":false},{"id":"b","text":"Una lámina plegada","is_correct":false},{"id":"c","text":"Una doble hélice","is_correct":true},{"id":"d","text":"Una sola hebra enroscada","is_correct":false}],"explanation":"El ADN son dos hebras enrolladas en doble hélice, con los pares de bases formando sus peldaños."},{"id":"q2","question":"¿Qué pareja de científicos publicó el modelo de doble hélice del ADN en 1953?","options":[{"id":"a","text":"James Watson y Francis Crick","is_correct":true},{"id":"b","text":"Charles Darwin y Alfred Russel Wallace","is_correct":false},{"id":"c","text":"Gregor Mendel y Thomas Hunt Morgan","is_correct":false},{"id":"d","text":"Rosalind Franklin y Maurice Wilkins","is_correct":false}],"explanation":"Watson y Crick construyeron el modelo en Cambridge a partir de datos de rayos X producidos por Rosalind Franklin."},{"id":"q3","question":"¿De quién fue la imagen de difracción de rayos X conocida como Foto 51, clave para revelar la estructura del ADN?","options":[{"id":"a","text":"Marie Curie","is_correct":false},{"id":"b","text":"Barbara McClintock","is_correct":false},{"id":"c","text":"Lise Meitner","is_correct":false},{"id":"d","text":"Rosalind Franklin","is_correct":true}],"explanation":"La Foto 51 de Franklin mostraba el patrón en X que reveló que el ADN es una hélice."},{"id":"q4","question":"¿Cuáles son las cuatro bases nitrogenadas del ADN?","options":[{"id":"a","text":"Adenina, guanina, citosina y uracilo","is_correct":false},{"id":"b","text":"Adenina, guanina, citosina y timina","is_correct":true},{"id":"c","text":"Adenina, guanina, fosfato y timina","is_correct":false},{"id":"d","text":"Adenina, glucosa, citosina y timina","is_correct":false}],"explanation":"El ADN usa adenina, guanina, citosina y timina; el uracilo sustituye a la timina en el ARN."},{"id":"q5","question":"En el ADN, ¿con qué base se empareja siempre la adenina?","options":[{"id":"a","text":"Con la guanina","is_correct":false},{"id":"b","text":"Con la citosina","is_correct":false},{"id":"c","text":"Con el uracilo","is_correct":false},{"id":"d","text":"Con la timina","is_correct":true}],"explanation":"La adenina se empareja con la timina (A–T) y la guanina con la citosina (G–C)."},{"id":"q6","question":"¿Qué monje descubrió las leyes básicas de la herencia en la década de 1860 experimentando con guisantes?","options":[{"id":"a","text":"Gregor Mendel","is_correct":true},{"id":"b","text":"Charles Darwin","is_correct":false},{"id":"c","text":"Thomas Hunt Morgan","is_correct":false},{"id":"d","text":"Hugo de Vries","is_correct":false}],"explanation":"Los experimentos de Mendel con guisantes en el jardín de su monasterio sentaron las bases de la genética."},{"id":"q7","question":"¿En qué estructura de la célula eucariota se encuentra la mayor parte de su ADN?","options":[{"id":"a","text":"En el ribosoma","is_correct":false},{"id":"b","text":"En el núcleo","is_correct":true},{"id":"c","text":"En el aparato de Golgi","is_correct":false},{"id":"d","text":"En el lisosoma","is_correct":false}],"explanation":"Casi todo el ADN está en el núcleo; las mitocondrias también tienen un pequeño genoma propio."},{"id":"q8","question":"¿Cuántos cromosomas contiene una célula humana típica?","options":[{"id":"a","text":"23","is_correct":false},{"id":"b","text":"44","is_correct":false},{"id":"c","text":"46","is_correct":true},{"id":"d","text":"48","is_correct":false}],"explanation":"Las células humanas llevan 46 cromosomas en 23 pares, un juego de cada progenitor."}]'::jsonb,
  null,
  array['ciencia', 'trivia', 'adn', 'genética', 'biología']::text[],
  3,
  'published',
