insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-volcanoes-and-earthquakes-trivia',
  'Volcanoes and Earthquakes Trivia: A Restless Planet',
  'Eight questions on the Ring of Fire, tectonic plates, seismic waves and the eruptions that shaped the map.',
  'trivia',
  'easy',
  'en',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"What is the name of the belt of frequent volcanic and seismic activity around the Pacific Ocean?","options":[{"id":"a","text":"The Alpine-Himalayan Belt","is_correct":false},{"id":"b","text":"The Ring of Fire","is_correct":true},{"id":"c","text":"The Mid-Atlantic Ridge","is_correct":false},{"id":"d","text":"The Great Rift Valley","is_correct":false}],"explanation":"The Ring of Fire traces the Pacific plate boundaries and hosts most of the world''s volcanoes."},{"id":"q2","question":"Which instrument detects and records the seismic waves of an earthquake?","options":[{"id":"a","text":"A barometer","is_correct":false},{"id":"b","text":"An anemometer","is_correct":false},{"id":"c","text":"A spectrometer","is_correct":false},{"id":"d","text":"A seismograph","is_correct":true}],"explanation":"A seismograph draws a seismogram, tracing the ground''s motion during a quake."},{"id":"q3","question":"Which scale rates the intensity of an earthquake by its observed effects on people and buildings?","options":[{"id":"a","text":"The Mercalli scale","is_correct":true},{"id":"b","text":"The Beaufort scale","is_correct":false},{"id":"c","text":"The Fujita scale","is_correct":false},{"id":"d","text":"The Mohs scale","is_correct":false}],"explanation":"The modified Mercalli scale goes from I (barely felt) to XII (total destruction)."},{"id":"q4","question":"Which type of plate boundary produces the deepest ocean trenches and the strongest earthquakes?","options":[{"id":"a","text":"Divergent","is_correct":false},{"id":"b","text":"Transform","is_correct":false},{"id":"c","text":"Convergent","is_correct":true},{"id":"d","text":"Hot spot","is_correct":false}],"explanation":"At convergent boundaries one plate subducts under another, building trenches and megaquakes."},{"id":"q5","question":"Which seismic waves travel fastest and arrive first at a seismograph?","options":[{"id":"a","text":"P-waves","is_correct":true},{"id":"b","text":"S-waves","is_correct":false},{"id":"c","text":"Surface waves","is_correct":false},{"id":"d","text":"Tsunami waves","is_correct":false}],"explanation":"Primary (P) waves compress rock like sound and outrun the slower secondary (S) waves."},{"id":"q6","question":"What is molten rock called while it is still beneath Earth''s surface?","options":[{"id":"a","text":"Lava","is_correct":false},{"id":"b","text":"Tephra","is_correct":false},{"id":"c","text":"Obsidian","is_correct":false},{"id":"d","text":"Magma","is_correct":true}],"explanation":"It is magma underground; it becomes lava once it erupts onto the surface."},{"id":"q7","question":"Which volcano''s eruption in 79 CE buried the Roman cities of Pompeii and Herculaneum?","options":[{"id":"a","text":"Mount Etna","is_correct":false},{"id":"b","text":"Stromboli","is_correct":false},{"id":"c","text":"Mount Vesuvius","is_correct":true},{"id":"d","text":"Krakatoa","is_correct":false}],"explanation":"Vesuvius buried both cities under ash and pumice, preserving them for centuries."},{"id":"q8","question":"The 1883 eruption of which volcano produced one of the loudest sounds in recorded history, heard thousands of kilometres away?","options":[{"id":"a","text":"Mount Pelée","is_correct":false},{"id":"b","text":"Mount Tambora","is_correct":false},{"id":"c","text":"Mount St. Helens","is_correct":false},{"id":"d","text":"Krakatoa","is_correct":true}],"explanation":"Krakatoa''s explosion was heard as far as 4,800 kilometres away and triggered huge tsunamis."}]'::jsonb,
  null,
  array['science', 'trivia', 'volcanoes', 'earthquakes', 'geology']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-volcanes-y-terremotos',
  'Trivia de volcanes y terremotos: un planeta inquieto',
  'Ocho preguntas sobre el Cinturón de Fuego, las placas tectónicas, las ondas sísmicas y las erupciones que marcaron la historia.',
  'trivia',
  'easy',
  'es',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"¿Cómo se llama el cinturón de intensa actividad volcánica y sísmica que rodea el océano Pacífico?","options":[{"id":"a","text":"El cinturón alpino-himalayo","is_correct":false},{"id":"b","text":"El Cinturón de Fuego","is_correct":true},{"id":"c","text":"La dorsal mesoatlántica","is_correct":false},{"id":"d","text":"El Gran Valle del Rift","is_correct":false}],"explanation":"El Cinturón de Fuego sigue los límites de la placa del Pacífico y concentra la mayoría de los volcanes del mundo."},{"id":"q2","question":"¿Qué instrumento detecta y registra las ondas sísmicas de un terremoto?","options":[{"id":"a","text":"El barómetro","is_correct":false},{"id":"b","text":"El anemómetro","is_correct":false},{"id":"c","text":"El espectrómetro","is_correct":false},{"id":"d","text":"El sismógrafo","is_correct":true}],"explanation":"El sismógrafo dibuja un sismograma que registra el movimiento del suelo durante el sismo."},{"id":"q3","question":"¿Qué escala mide la intensidad de un terremoto según sus efectos observados en personas y edificios?","options":[{"id":"a","text":"La escala de Mercalli","is_correct":true},{"id":"b","text":"La escala de Beaufort","is_correct":false},{"id":"c","text":"La escala de Fujita","is_correct":false},{"id":"d","text":"La escala de Mohs","is_correct":false}],"explanation":"La escala de Mercalli modificada va de I (apenas perceptible) a XII (destrucción total)."},{"id":"q4","question":"¿Qué tipo de límite de placas produce las fosas oceánicas más profundas y los terremotos más fuertes?","options":[{"id":"a","text":"El límite divergente","is_correct":false},{"id":"b","text":"El límite de transformación","is_correct":false},{"id":"c","text":"El límite convergente","is_correct":true},{"id":"d","text":"El punto caliente","is_correct":false}],"explanation":"En los límites convergentes una placa se subduce bajo otra, formando fosas y megaterremotos."},{"id":"q5","question":"¿Qué ondas sísmicas viajan más rápido y llegan primero al sismógrafo?","options":[{"id":"a","text":"Las ondas P","is_correct":true},{"id":"b","text":"Las ondas S","is_correct":false},{"id":"c","text":"Las ondas superficiales","is_correct":false},{"id":"d","text":"Las olas del tsunami","is_correct":false}],"explanation":"Las ondas primarias (P) comprimen la roca como el sonido y superan a las secundarias (S)."},{"id":"q6","question":"¿Cómo se llama la roca fundida mientras permanece bajo la superficie terrestre?","options":[{"id":"a","text":"Lava","is_correct":false},{"id":"b","text":"Tefra","is_correct":false},{"id":"c","text":"Obsidiana","is_correct":false},{"id":"d","text":"Magma","is_correct":true}],"explanation":"Es magma bajo tierra; se convierte en lava cuando sale a la superficie en una erupción."},{"id":"q7","question":"¿Qué volcán enterró con su erupción del año 79 las ciudades romanas de Pompeya y Herculano?","options":[{"id":"a","text":"El Etna","is_correct":false},{"id":"b","text":"El Estrómboli","is_correct":false},{"id":"c","text":"El Vesubio","is_correct":true},{"id":"d","text":"El Krakatoa","is_correct":false}],"explanation":"El Vesubio sepultó ambas ciudades bajo ceniza y piedra pómez, conservándolas durante siglos."},{"id":"q8","question":"¿La erupción de 1883 de qué volcán produjo uno de los sonidos más fuertes registrados, oído a miles de kilómetros?","options":[{"id":"a","text":"El monte Pelée","is_correct":false},{"id":"b","text":"El Tambora","is_correct":false},{"id":"c","text":"El Santa Elena","is_correct":false},{"id":"d","text":"El Krakatoa","is_correct":true}],"explanation":"La explosión del Krakatoa se escuchó a unos 4.800 kilómetros y provocó enormes tsunamis."}]'::jsonb,
  null,
  array['ciencia', 'trivia', 'volcanes', 'terremotos', 'geología']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-periodic-table-trivia',
  'Periodic Table Trivia: Elements, Groups and Symbols',
  'Eight questions on Mendeleev''s table: atomic numbers, noble gases, alkali metals and the symbols behind each element.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"Which chemist published the first widely recognized periodic table of the elements in 1869?","options":[{"id":"a","text":"Antoine Lavoisier","is_correct":false},{"id":"b","text":"John Dalton","is_correct":false},{"id":"c","text":"Dmitri Mendeleev","is_correct":true},{"id":"d","text":"Henry Moseley","is_correct":false}],"explanation":"Mendeleev arranged elements by atomic weight and left gaps for elements not yet discovered."},{"id":"q2","question":"What does an element''s atomic number represent?","options":[{"id":"a","text":"Its number of neutrons","is_correct":false},{"id":"b","text":"Its number of protons","is_correct":true},{"id":"c","text":"Its total number of nucleons","is_correct":false},{"id":"d","text":"Its electrons in the outermost shell","is_correct":false}],"explanation":"The atomic number counts the protons in the nucleus and fixes the element''s identity."},{"id":"q3","question":"What is the chemical symbol for gold?","options":[{"id":"a","text":"Ag","is_correct":false},{"id":"b","text":"Go","is_correct":false},{"id":"c","text":"Gd","is_correct":false},{"id":"d","text":"Au","is_correct":true}],"explanation":"Au comes from aurum, the Latin word for gold; Ag (silver) comes from argentum."},{"id":"q4","question":"What are the vertical columns of the periodic table called?","options":[{"id":"a","text":"Groups","is_correct":true},{"id":"b","text":"Periods","is_correct":false},{"id":"c","text":"Blocks","is_correct":false},{"id":"d","text":"Series","is_correct":false}],"explanation":"Columns are groups of elements with similar properties; rows are called periods."},{"id":"q5","question":"Which group of the periodic table contains the noble gases such as helium, neon and argon?","options":[{"id":"a","text":"Group 1","is_correct":false},{"id":"b","text":"Group 2","is_correct":false},{"id":"c","text":"Group 17","is_correct":false},{"id":"d","text":"Group 18","is_correct":true}],"explanation":"Group 18, the rightmost column, holds the noble gases, which barely react with other elements."},{"id":"q6","question":"Which is the lightest element and the most abundant in the universe?","options":[{"id":"a","text":"Helium","is_correct":false},{"id":"b","text":"Hydrogen","is_correct":true},{"id":"c","text":"Oxygen","is_correct":false},{"id":"d","text":"Carbon","is_correct":false}],"explanation":"Hydrogen, with a single proton, makes up about three quarters of normal matter in the universe."},{"id":"q7","question":"Sodium and potassium are soft, highly reactive metals that belong to which group?","options":[{"id":"a","text":"The halogens","is_correct":false},{"id":"b","text":"The alkaline earth metals","is_correct":false},{"id":"c","text":"The alkali metals","is_correct":true},{"id":"d","text":"The transition metals","is_correct":false}],"explanation":"Group 1 metals (except hydrogen) are the alkali metals, which react vigorously with water."},{"id":"q8","question":"Which is the only metal that is liquid at room temperature?","options":[{"id":"a","text":"Mercury","is_correct":true},{"id":"b","text":"Lead","is_correct":false},{"id":"c","text":"Aluminium","is_correct":false},{"id":"d","text":"Tin","is_correct":false}],"explanation":"Mercury melts at about minus 39 °C; the only other element liquid at room temperature is bromine, a nonmetal."}]'::jsonb,
  null,
  array['science', 'trivia', 'periodic table', 'chemistry', 'elements']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-elementos-quimicos',
  'Trivia de la tabla periódica: elementos, grupos y símbolos',
  'Ocho preguntas sobre la tabla de Mendeléyev: números atómicos, gases nobles, metales alcalinos y los símbolos de cada elemento.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"¿Qué químico publicó en 1869 la primera tabla periódica de los elementos ampliamente reconocida?","options":[{"id":"a","text":"Antoine Lavoisier","is_correct":false},{"id":"b","text":"John Dalton","is_correct":false},{"id":"c","text":"Dmitri Mendeléyev","is_correct":true},{"id":"d","text":"Henry Moseley","is_correct":false}],"explanation":"Mendeléyev ordenó los elementos por peso atómico y dejó huecos para los aún no descubiertos."},{"id":"q2","question":"¿Qué representa el número atómico de un elemento?","options":[{"id":"a","text":"Su número de neutrones","is_correct":false},{"id":"b","text":"Su número de protones","is_correct":true},{"id":"c","text":"Su número total de nucleones","is_correct":false},{"id":"d","text":"Sus electrones de la capa externa","is_correct":false}],"explanation":"El número atómico cuenta los protones del núcleo y define la identidad del elemento."},{"id":"q3","question":"¿Cuál es el símbolo químico del oro?","options":[{"id":"a","text":"Ag","is_correct":false},{"id":"b","text":"Go","is_correct":false},{"id":"c","text":"Gd","is_correct":false},{"id":"d","text":"Au","is_correct":true}],"explanation":"Au viene de aurum, el nombre latino del oro; Ag (plata) viene de argentum."},{"id":"q4","question":"¿Cómo se llaman las columnas verticales de la tabla periódica?","options":[{"id":"a","text":"Grupos","is_correct":true},{"id":"b","text":"Periodos","is_correct":false},{"id":"c","text":"Bloques","is_correct":false},{"id":"d","text":"Series","is_correct":false}],"explanation":"Las columnas son grupos de elementos con propiedades similares; las filas se llaman periodos."},{"id":"q5","question":"¿Qué grupo de la tabla periódica contiene los gases nobles como el helio, el neón y el argón?","options":[{"id":"a","text":"El grupo 1","is_correct":false},{"id":"b","text":"El grupo 2","is_correct":false},{"id":"c","text":"El grupo 17","is_correct":false},{"id":"d","text":"El grupo 18","is_correct":true}],"explanation":"El grupo 18, la columna del extremo derecho, reúne los gases nobles, que casi no reaccionan con otros elementos."},{"id":"q6","question":"¿Cuál es el elemento más ligero y el más abundante del universo?","options":[{"id":"a","text":"El helio","is_correct":false},{"id":"b","text":"El hidrógeno","is_correct":true},{"id":"c","text":"El oxígeno","is_correct":false},{"id":"d","text":"El carbono","is_correct":false}],"explanation":"El hidrógeno, con un solo protón, forma cerca de tres cuartas partes de la materia normal del universo."},{"id":"q7","question":"El sodio y el potasio son metales blandos y muy reactivos que pertenecen a qué grupo?","options":[{"id":"a","text":"A los halógenos","is_correct":false},{"id":"b","text":"A los metales alcalinotérreos","is_correct":false},{"id":"c","text":"A los metales alcalinos","is_correct":true},{"id":"d","text":"A los metales de transición","is_correct":false}],"explanation":"Los metales del grupo 1 (salvo el hidrógeno) son los alcalinos, que reaccionan con violencia con el agua."},{"id":"q8","question":"¿Cuál es el único metal que es líquido a temperatura ambiente?","options":[{"id":"a","text":"El mercurio","is_correct":true},{"id":"b","text":"El plomo","is_correct":false},{"id":"c","text":"El aluminio","is_correct":false},{"id":"d","text":"El estaño","is_correct":false}],"explanation":"El mercurio funde a unos 39 °C bajo cero; el único otro elemento líquido a temperatura ambiente es el bromo, un no metal."}]'::jsonb,
  null,
  array['ciencia', 'trivia', 'tabla periódica', 'química', 'elementos']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-deep-sea-trivia',
  'Deep Sea Trivia: Life in the Ocean''s Dark Zones',
  'Eight questions on trenches, abyssal zones, bioluminescence and the strange creatures of the deep ocean.',
  'trivia',
  'easy',
  'en',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"What is the name of the deepest known point of the ocean, in the Mariana Trench?","options":[{"id":"a","text":"Horizon Deep","is_correct":false},{"id":"b","text":"Sirena Deep","is_correct":false},{"id":"c","text":"Challenger Deep","is_correct":true},{"id":"d","text":"Brownson Deep","is_correct":false}],"explanation":"Challenger Deep bottoms out near 10,900 metres below sea level, deeper than Everest is tall."},{"id":"q2","question":"How is the ocean zone between roughly 4,000 and 6,000 metres of depth, in total darkness, called?","options":[{"id":"a","text":"The photic zone","is_correct":false},{"id":"b","text":"The abyssal zone","is_correct":true},{"id":"c","text":"The bathyal zone","is_correct":false},{"id":"d","text":"The hadal zone","is_correct":false}],"explanation":"The abyssal zone covers the deep seafloor; the hadal zone, deeper still, is the realm of trenches."},{"id":"q3","question":"What is the ability of many deep-sea animals to produce their own light called?","options":[{"id":"a","text":"Photosynthesis","is_correct":false},{"id":"b","text":"Fluorescence","is_correct":false},{"id":"c","text":"Iridescence","is_correct":false},{"id":"d","text":"Bioluminescence","is_correct":true}],"explanation":"Bioluminescence is light made by a chemical reaction inside the organism, used to hunt or hide."},{"id":"q4","question":"Hydrothermal vent communities get their energy not from sunlight but from which process?","options":[{"id":"a","text":"Chemosynthesis","is_correct":true},{"id":"b","text":"Photosynthesis","is_correct":false},{"id":"c","text":"Fermentation","is_correct":false},{"id":"d","text":"Phagocytosis","is_correct":false}],"explanation":"Vent bacteria turn chemicals like hydrogen sulfide into food, feeding whole ecosystems in the dark."},{"id":"q5","question":"Which crewed submersible reached the bottom of the Mariana Trench for the first time in 1960?","options":[{"id":"a","text":"Alvin","is_correct":false},{"id":"b","text":"Nautilus","is_correct":false},{"id":"c","text":"Trieste","is_correct":true},{"id":"d","text":"Limiting Factor","is_correct":false}],"explanation":"Jacques Piccard and Don Walsh descended in the bathyscaphe Trieste to Challenger Deep."},{"id":"q6","question":"Which deep-sea fish has a transparent head, with its eyes sealed inside a clear dome?","options":[{"id":"a","text":"The anglerfish","is_correct":false},{"id":"b","text":"The gulper eel","is_correct":false},{"id":"c","text":"The viperfish","is_correct":false},{"id":"d","text":"The barreleye","is_correct":true}],"explanation":"The barreleye''s green eyes rotate inside its see-through skull to track prey above."},{"id":"q7","question":"Which deep-sea fish attracts prey with a glowing lure that dangles in front of its mouth?","options":[{"id":"a","text":"The anglerfish","is_correct":true},{"id":"b","text":"The lanternfish","is_correct":false},{"id":"c","text":"The blobfish","is_correct":false},{"id":"d","text":"The oarfish","is_correct":false}],"explanation":"Female anglerfish carry a luminous lure, fuelled by glowing bacteria, at the tip of a fin ray."},{"id":"q8","question":"By about how much does water pressure increase for every 10 metres of depth in the ocean?","options":[{"id":"a","text":"By 0.1 atmospheres","is_correct":false},{"id":"b","text":"By 1 atmosphere","is_correct":true},{"id":"c","text":"By 10 atmospheres","is_correct":false},{"id":"d","text":"By 100 atmospheres","is_correct":false}],"explanation":"Pressure grows about one atmosphere per 10 metres, so the deep sea is under crushing loads."}]'::jsonb,
  null,
  array['science', 'trivia', 'deep sea', 'ocean', 'marine biology']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-fondo-del-mar',
  'Trivia del fondo del mar: vida en la oscuridad del océano',
  'Ocho preguntas sobre fosas oceánicas, zonas abisales, bioluminiscencia y las extrañas criaturas del mar profundo.',
  'trivia',
  'easy',
  'es',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"¿Cómo se llama el punto más profundo conocido del océano, en la fosa de las Marianas?","options":[{"id":"a","text":"Horizon Deep","is_correct":false},{"id":"b","text":"Sirena Deep","is_correct":false},{"id":"c","text":"El abismo Challenger","is_correct":true},{"id":"d","text":"Brownson Deep","is_correct":false}],"explanation":"El abismo Challenger llega a unos 10.900 metros bajo el nivel del mar, más que la altura del Everest."},{"id":"q2","question":"¿Cómo se llama la zona del océano entre unos 4.000 y 6.000 metros de profundidad, en oscuridad total?","options":[{"id":"a","text":"La zona fótica","is_correct":false},{"id":"b","text":"La zona abisal","is_correct":true},{"id":"c","text":"La zona batial","is_correct":false},{"id":"d","text":"La zona hadal","is_correct":false}],"explanation":"La zona abisal cubre el fondo marino profundo; la zona hadal, aún más honda, es la de las fosas."},{"id":"q3","question":"¿Cómo se llama la capacidad de muchos animales del mar profundo de producir su propia luz?","options":[{"id":"a","text":"Fotosíntesis","is_correct":false},{"id":"b","text":"Fluorescencia","is_correct":false},{"id":"c","text":"Iridiscencia","is_correct":false},{"id":"d","text":"Bioluminiscencia","is_correct":true}],"explanation":"La bioluminiscencia es luz producida por una reacción química del organismo, usada para cazar o esconderse."},{"id":"q4","question":"Las comunidades de las fumarolas hidrotermales obtienen su energía no del sol sino de qué proceso?","options":[{"id":"a","text":"La quimiosíntesis","is_correct":true},{"id":"b","text":"La fotosíntesis","is_correct":false},{"id":"c","text":"La fermentación","is_correct":false},{"id":"d","text":"La fagocitosis","is_correct":false}],"explanation":"Las bacterias de las fumarolas convierten compuestos como el sulfuro de hidrógeno en alimento para todo un ecosistema."},{"id":"q5","question":"¿Qué sumergible tripulado llegó por primera vez al fondo de la fosa de las Marianas en 1960?","options":[{"id":"a","text":"El Alvin","is_correct":false},{"id":"b","text":"El Nautilus","is_correct":false},{"id":"c","text":"El Trieste","is_correct":true},{"id":"d","text":"El Limiting Factor","is_correct":false}],"explanation":"Jacques Piccard y Don Walsh bajaron en el batiscafo Trieste hasta el abismo Challenger."},{"id":"q6","question":"¿Qué pez de las profundidades tiene la cabeza transparente, con los ojos dentro de una cúpula?","options":[{"id":"a","text":"El pez rape","is_correct":false},{"id":"b","text":"La anguila pelícano","is_correct":false},{"id":"c","text":"El pez víbora","is_correct":false},{"id":"d","text":"El pez duende","is_correct":true}],"explanation":"Los ojos verdes del pez duende giran dentro de su cráneo transparente para seguir a sus presas."},{"id":"q7","question":"¿Qué pez de las profundidades atrae a sus presas con un señuelo luminoso que cuelga frente a su boca?","options":[{"id":"a","text":"El pez rape","is_correct":true},{"id":"b","text":"El pez linterna","is_correct":false},{"id":"c","text":"El pez borrón","is_correct":false},{"id":"d","text":"El pez remo","is_correct":false}],"explanation":"Las hembras del pez rape llevan un señuelo luminoso, alimentado por bacterias brillantes, en la punta de una espina."},{"id":"q8","question":"¿En cuánto aumenta aproximadamente la presión del agua por cada 10 metros de profundidad en el océano?","options":[{"id":"a","text":"En 0,1 atmósferas","is_correct":false},{"id":"b","text":"En 1 atmósfera","is_correct":true},{"id":"c","text":"En 10 atmósferas","is_correct":false},{"id":"d","text":"En 100 atmósferas","is_correct":false}],"explanation":"La presión crece cerca de una atmósfera cada 10 metros, por eso el fondo marino soporta cargas enormes."}]'::jsonb,
  null,
  array['ciencia', 'trivia', 'mar profundo', 'océano', 'biología marina']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

